const asm  = $('Assemble row').first().json;
const path = row.output_image_path;
const url  = `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${path}`;
return [{ json: {
  generation_id:        row.id,
  user_id:              row.user_id,
  session_id:           row.session_id,
  kind:                 row.kind,
  parent_generation_id: row.parent_generation_id,
  model_id:             row.model_id,
  latency_ms:           row.latency_ms,
  cost_usd:             row.cost_usd,
  room_type:            row.room_type,
  style_tag:            row.style_tag,
  output_url:           url,
